#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include "ompvv.h"
#include <math.h>

#define N 1024

int test_multiply() {
  int a[N];
  int errors = 0;
  int num_threads[N];
  srand(1);

  for (int x = 0; x < N; ++x) {
    a[x] = 1 + (int) rand() / (double) RAND_MAX;
    num_threads[x] = -x;
  }

  int result = 1;
  int host_result;

  for (int x = 0; x < N; x = x + 16) {
    result = 1;
#pragma omp parallel num_threads(OMPVV_NUM_THREADS_HOST)
    {
#pragma omp loop reduction(*:result)
      for (int y = 0; y < 16; ++y) {
        result *= a[x + y];
      }
#pragma omp for
      for (int y = 0; y < 16; ++y) {
        num_threads[x + y] = omp_get_num_threads();
      }
    }
    host_result = 1;
    for (int y = 0; y < 16; ++y) {
      host_result *= a[x + y];
    }
    OMPVV_TEST_AND_SET_VERBOSE(errors, host_result != result);
    OMPVV_INFOMSG_IF(host_result != result, "Loop directive result is %d and expected result is %d.", result, host_result);
  }

