                for (int i = 0 ; i < N ; ++i)
                {
                    # pragma omp taskgraph graph_id(i)
                    {
                        ++x[i];
                        for (int k = 0 ; k < 3 ; ++k)
                        {
                            # pragma omp task depend(out: y) shared(y)
                            {
                                # pragma omp atomic
                                    ++y[i];
                            }
                        }
                    }
                }
